#!/usr/bin/env bash
# step103 — Batch 2: guest-cart persistence + merge into the account on login
# (follows the customer across devices). Adds customer_carts, routes/cartsync.js,
# cart.js sync, an auth flag + cart.js cache bump. Idempotent; rolls back.
set -euo pipefail
APP=/opt/gsz
TS=$(date +%Y%m%d-%H%M%S)
BAK=$APP/.bak-step103-$TS
mkdir -p "$BAK/routes" "$BAK/js" "$BAK/partials"
cp "$APP/server.js" "$BAK/server.js"
cp "$APP/public/js/cart.js" "$BAK/js/cart.js"
cp "$APP/views/partials/store_bottom.ejs" "$BAK/partials/store_bottom.ejs"
restore(){ echo "!! rollback"; cp "$BAK/server.js" "$APP/server.js"; cp "$BAK/js/cart.js" "$APP/public/js/cart.js"; cp "$BAK/partials/store_bottom.ejs" "$APP/views/partials/store_bottom.ejs"; rm -f "$APP/routes/cartsync.js"; pm2 restart gsz --update-env >/dev/null 2>&1 || true; }
trap 'restore' ERR
cd "$APP"

echo "==> migrate: customer_carts"
node <<'NODE'
require('dotenv').config();
const { Pool } = require('pg');
const p = new Pool({ host:process.env.DB_HOST, port:process.env.DB_PORT, database:process.env.DB_NAME, user:process.env.DB_USER, password:process.env.DB_PASS });
p.query("CREATE TABLE IF NOT EXISTS customer_carts(customer_id integer PRIMARY KEY REFERENCES customers(id) ON DELETE CASCADE, items jsonb NOT NULL DEFAULT '[]', updated_at timestamptz NOT NULL DEFAULT now())")
  .then(()=>{ console.log('   customer_carts ready'); return p.end(); }).catch(e=>{ console.error('MIGRATION FAIL: '+e.message); p.end(); process.exit(1); });
NODE

echo "==> write cartsync.js + cart.js"
base64 -d > "$APP/routes/cartsync.js" <<'B64'

B64
base64 -d > "$APP/public/js/cart.js" <<'B64'

B64

echo "==> patch server.js (mount cartsync)"
node <<'NODE'
const fs=require('fs'); const f='/opt/gsz/server.js'; let s=fs.readFileSync(f,'utf8');
if(s.indexOf('routes/cartsync')>=0){ console.log('   server already'); }
else {
  const a="const trialsRouter = require('./routes/trials')(pool);\napp.use('/', trialsRouter);";
  if(s.indexOf(a)<0){ console.error('!! trials mount anchor not found'); process.exit(2); }
  s=s.replace(a, a+"\nconst cartSyncRouter = require('./routes/cartsync')(pool);\napp.use('/', cartSyncRouter);");
  fs.writeFileSync(f,s); console.log('   server patched');
}
NODE

echo "==> patch store_bottom.ejs (auth flag + cart.js cache bump)"
node <<'NODE'
const fs=require('fs'); const f='/opt/gsz/views/partials/store_bottom.ejs'; let s=fs.readFileSync(f,'utf8');
if(s.indexOf('__GSZAUTH')>=0){ console.log('   store_bottom already'); }
else {
  const m=s.match(/<script src="\/static\/js\/cart\.js\?v=\d+" defer><\/script>/);
  if(!m){ console.error('!! cart.js script tag not found'); process.exit(3); }
  s=s.replace(m[0], "<script>window.__GSZAUTH = <%= locals.customer ? 'true' : 'false' %>;</script>\n"+m[0]);
  s=s.replace(/cart\.js\?v=(\d+)/, function(mm,n){ return 'cart.js?v='+(parseInt(n,10)+1); });
  fs.writeFileSync(f,s); console.log('   store_bottom patched (auth flag + cart.js bump)');
}
NODE

echo "==> node --check + ejs compile + restart"
node --check "$APP/routes/cartsync.js"; node --check "$APP/public/js/cart.js"; node --check "$APP/server.js"
node -e "const ejs=require('ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$APP/views/partials/store_bottom.ejs','utf8'),{filename:'x'});console.log('   store_bottom compiles');"
pm2 restart gsz --update-env >/dev/null; sleep 3
grep -q '</html>' <<<"$(curl -s -m 15 http://127.0.0.1:3900/ || true)" || { echo "!! home broken"; false; }
grep -q '"items"' <<<"$(curl -s -m 10 http://127.0.0.1:3900/api/cart || true)" || { echo "!! /api/cart not responding"; false; }
trap - ERR
echo "==> step103 OK — account cart sync + guest-cart merge on login. Backup: $BAK"
